cat > /tmp/ivx-debug-console.mjs <<'EOF'
import { chromium } from 'playwright';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 375, height: 812 } });

const consoleMessages = [];
const pageErrors = [];
const failedRequests = [];

page.on('console', msg => {
  consoleMessages.push({ type: msg.type(), text: msg.text().slice(0, 500) });
});
page.on('pageerror', err => {
  pageErrors.push(err.message.slice(0, 500));
});
page.on('requestfailed', req => {
  failedRequests.push({ url: req.url().slice(0, 200), failure: req.failure()?.errorText });
});

await page.goto('https://ivxholding.com/app/', { waitUntil: 'networkidle' });
await page.waitForTimeout(8000);

// Check CSS
const cssInfo = await page.evaluate(() => {
  const stylesheets = Array.from(document.querySelectorAll('link[rel="stylesheet"]'));
  const styleTags = document.querySelectorAll('style').length;
  return {
    stylesheetCount: stylesheets.length,
    stylesheets: stylesheets.map(s => s.href),
    styleTagCount: styleTags,
    bodyBg: window.getComputedStyle(document.body).backgroundColor,
    bodyColor: window.getComputedStyle(document.body).color,
    bodyFontFamily: window.getComputedStyle(document.body).fontFamily,
    bodyDisplay: window.getComputedStyle(document.body).display,
    bodyVisibility: window.getComputedStyle(document.body).visibility,
    bodyOpacity: window.getComputedStyle(document.body).opacity,
    rootHTML_height: document.documentElement.scrollHeight,
    body_height: document.body.scrollHeight,
  };
});

// Check what elements are actually visible
const visibleElements = await page.evaluate(() => {
  const els = Array.from(document.querySelectorAll('div, span, p, h1, h2, input, button, a, img'));
  const visible = els.filter(el => {
    const rect = el.getBoundingClientRect();
    const style = window.getComputedStyle(el);
    return rect.width > 0 && rect.height > 0 && style.display !== 'none' && style.visibility !== 'hidden' && style.opacity !== '0';
  });
  return visible.slice(0, 20).map(el => ({
    tag: el.tagName,
    text: el.innerText?.slice(0, 50),
    w: el.getBoundingClientRect().width,
    h: el.getBoundingClientRect().height,
    bg: window.getComputedStyle(el).backgroundColor,
    color: window.getComputedStyle(el).color,
  }));
});

await browser.close();

console.log('=== CSS INFO ===');
console.log(JSON.stringify(cssInfo, null, 2));
console.log('\n=== CONSOLE ERRORS ===');
consoleMessages.filter(m => m.type === 'error').forEach(m => console.log(`[ERROR] ${m.text}`));
console.log('\n=== CONSOLE WARNINGS ===');
consoleMessages.filter(m => m.type === 'warning').forEach(m => console.log(`[WARN] ${m.text}`));
console.log('\n=== PAGE ERRORS ===');
pageErrors.forEach(e => console.log(e));
console.log('\n=== FAILED REQUESTS ===');
failedRequests.forEach(r => console.log(`${r.url} — ${r.failure}`));
console.log('\n=== ALL CONSOLE MESSAGES (first 30) ===');
consoleMessages.slice(0, 30).forEach(m => console.log(`[${m.type}] ${m.text}`));
console.log('\n=== VISIBLE ELEMENTS ===');
visibleElements.forEach(e => console.log(`${e.tag} (${e.w}x${e.h}) bg=${e.bg} color=${e.color} text="${e.text}"`));
console.log('\n=== TOTAL CONSOLE MSGS:', consoleMessages.length, '===');
console.log('=== TOTAL PAGE ERRORS:', pageErrors.length, '===');
console.log('=== TOTAL FAILED REQUESTS:', failedRequests.length, '===');
EOF
