let token = null;
for (const line of lines) {
  const [key, value] = line.split(/\s+/);
  if (value === `https://github.com/${repo}`) {
    const m = key.match(/x-access-token:([^@]+)@github\.com/);
    if (m) { token = m[1]; break; }
  }
}
if (!token) { console.error('No token found'); process.exit(1); }

const res = await fetch(`https://api.github.com/repos/${repo}/actions/workflows/${workflow}/dispatches`, {
  method: 'POST',
  headers: {
    'Accept': 'application/vnd.github+json',
    'Authorization': `Bearer ${token}`,
    'X-GitHub-Api-Version': '2022-11-28',
    'Content-Type': 'application/json',
  },
  body: JSON.stringify({ ref: 'main', inputs: { deployWebApp: 'true' } }),
});

console.log(`Dispatch status: ${res.status} ${res.statusText}`);
const text = await res.text();
if (text) console.log(`Body: ${text.slice(0, 300)}`);
process.exit(res.status === 204 ? 0 : 1);
EOF
