const repo = 'ibb142/ivx-holdings-platform';
const cfg = execSync('git config --get-regexp "^url\\..*\\.insteadof$"', { encoding: 'utf8' }).trim();
const lines = cfg.split('\n');
let token = null;
for (const line of lines) {
  const [key, value] = line.split(/\s+/);
  if (value === `https://github.com/${repo}`) {
    const m = key.match(/x-access-token:([^@]+)@github\.com/);
    if (m) { token = m[1]; break; }
  }
}

const res = await fetch(`https://api.github.com/repos/${repo}/actions/runs?per_page=3`, {
  headers: {
    'Accept': 'application/vnd.github+json',
    'Authorization': `Bearer ${token}`,
    'X-GitHub-Api-Version': '2022-11-28',
  },
});

const data = await res.json();
const runs = data.workflow_runs || [];
for (const run of runs.slice(0, 3)) {
  console.log(`#${run.run_number} | ${run.status} | ${run.conclusion || '...'} | ${run.head_sha?.slice(0,8)} | ${run.display_title || run.name} | ${run.created_at}`);
}
EOF
sleep 30
bun run /tmp/check-workflow2.mjs

